export const BODY: string = "\n<p>تصویر کولاج کئی تصویروں کو ایک تصویر میں بدل دیتا ہے۔ یہ لمحوں کا سیٹ ایک ساتھ دکھاتا ہے: سفر، مصنوعات رینج، پہلے اور بعد، یا خاندانی اجتماع۔ ایک کولاج الگ تصویروں کی قطار سے زیادہ کہتا ہے، اور یہ کہیں بھی فٹ ہوتا ہے جہاں ایک تصویر فٹ ہوتی ہے۔</p>\n<p><a href=\"/ur/tasveer-collage-maker/\">تصویر کولاج میکر</a> آپ کی تصویروں کو 2 بہ 2 اور 3 بہ 3 گرڈ یا عمودی اور افقی پٹیوں میں ترتیب دیتا ہے، گھسیٹ کر بدلنے، ایڈجسٹ کرنے والی تقسیم، خالی جگہیں، گول کونے، اور 4000 پکسل تک برآمد کے ساتھ۔ یہ مکمل طور پر آپ کے براؤزر میں چلتا ہے۔</p>\n<p>یہ رہنما لے آؤٹ، ترتیب کنٹرول، فریمنگ اختیار، اور برآمد انتخاب بتاتا ہے، اور دکھاتا ہے کہ کون سا لے آؤٹ کس کام کو سوٹ کرتا ہے۔ چاہے آپ سوشل پوسٹ بنائیں، پرنٹ بنائیں، یا تحفہ بنائیں، کولاج وہی سادہ خیال ہے۔</p>\n<h2 id=\"what-is-a-collage-maker\">کولاج میکر کیا ہے؟</h2>\n<p>کولاج میکر کئی تصویروں کو مشترکہ کینوس پر ایک تصویر میں ترتیب دیتا ہے۔ ہر تصویر سیل میں بیٹھتی ہے، اور سیل مل کر گرڈ یا پٹی بناتے ہیں۔ نتیجہ ایک تصویر فائل ہے جس میں تمام تصویریں ایک ساتھ ہیں۔</p>\n<p>ٹول تصویر ایڈیٹر سے مختلف ہے۔ یہ خود تصویروں کو نہیں بدلتا؛ یہ انہیں ترتیب دیتا ہے۔ آپ لے آؤٹ چنتے ہیں، تصویریں رکھتے ہیں، فاصلہ ایڈجسٹ کرتے ہیں، اور جوڑی ہوئی تصویر کو JPG یا PNG کے طور پر برآمد کرتے ہیں۔</p>\n<p>کولاج سوشل پوسٹ کے لیے استعمال ہوتے ہیں، جہاں ایک تصویر کئی لمحے رکھتی ہے؛ مصنوعات لسٹنگ کے لیے، جہاں ایک تصویر رینج دکھاتی ہے؛ پہلے اور بعد موازنہ کے لیے، جہاں دو تصویریں ساتھ بیٹھتی ہیں؛ اور پرنٹ اور تحفوں کے لیے، جہاں کئی یادیں ایک فریم شیئر کرتی ہیں۔</p>\n<h2 id=\"layouts-grids-and-strips\">لے آؤٹ: گرڈ اور پٹیاں</h2>\n<p>ٹول دو گرڈ لے آؤٹ اور دو پٹی لے آؤٹ دیتا ہے۔ 2 بہ 2 گرڈ مربع میں چار تصویریں رکھتا ہے، اور 3 بہ 3 گرڈ نو رکھتا ہے۔ عمودی پٹی تصویروں کو لمبے کالم میں ڈھیر کرتی ہے، اور افقی پٹی انہیں چوڑی قطار میں لگاتی ہے۔</p>\n<p>لے آؤٹ آپ کی اپ لوڈ شدہ تصویروں کی تعداد سے خود بخود چنا جاتا ہے۔ پانچ یا زیادہ تصویریں ڈالنے سے 3 بہ 3 گرڈ چن لیا جاتا ہے، جبکہ چار یا کم سے 2 بہ 2 گرڈ چن لیا جاتا ہے۔ آپ اپ لوڈ کے بعد کسی بھی وقت لے آؤٹ بدل سکتے ہیں۔</p>\n<p>گرڈ ان تصویروں کے سیٹ کو سوٹ کرتے ہیں جو ایک ساتھ ہوں: سفر، تقریب یا مصنوعات رینج۔ مربع شکل فیڈ، لسٹنگ اور تھمب نیل کو سوٹ کرتی ہے، اور برابر سیل ہر تصویر کو ایک جیسا وزن دیتے ہیں۔</p>\n<h2 id=\"uploading-photos\">تصویریں اپ لوڈ کرنا</h2>\n<p>اپنی تصویریں اپ لوڈ والے حصے پر گھسیٹ دیں، یا اپنے آلے سے چننے کے لیے اس پر کلک کریں۔ ٹول 20 MB تک JPG، PNG، WebP، HEIC، GIF، BMP اور SVG فائلیں قبول کرتا ہے، اس لیے فون کی تصویریں، اسکرین شاٹ اور گرافکس سب بغیر تبدیلی کے کام کرتے ہیں۔</p>\n<p>فارمیٹ کا مرکب اپ لوڈ کرنا ٹھیک کام کرتا ہے۔ آئی فون کی HEIC تصویر، PNG اسکرین شاٹ، اور کیمرے کی JPG ایک ہی کولاج میں بیٹھ سکتی ہیں، کیونکہ ٹول ہر ایک کو دکھانے اور برآمد کے لیے بدلتا ہے۔ فارمیٹ صرف حتمی برآمد انتخاب کے لیے اہم ہیں۔</p>\n<p>تصویروں کی تعداد شروعاتی لے آؤٹ طے کرتی ہے۔ پانچ یا زیادہ تصویریں 3 بہ 3 گرڈ خود بخود چنتی ہیں، اور چار یا کم 2 بہ 2 گرڈ خود بخود چنتی ہیں۔ اگر آپ گرڈ کے سیل سے کم تصویریں اپ لوڈ کریں تو خالی سیل مزید تصویروں کا انتظار کرتے ہیں یا خالی رہتے ہیں جب تک آپ انہیں شامل نہ کریں۔</p>\n<h2 id=\"drag-swap-and-tap-swap\">گھسیٹ کر بدلنا اور ٹیپ کر کے بدلنا</h2>\n<p>ڈیسک ٹاپ پر تصویریں ترتیب دینا گھسیٹ کر ڈالنے کا کام ہے: تصویر اٹھائیں اور اسے دوسرے سیل پر ڈالیں، اور دو تصویریں جگہ بدل لیتی ہیں۔ تبدیلی فوراً ہوتی ہے، اور آپ برآمد سے پہلے جتنی بار چاہیں دوبارہ ترتیب دے سکتے ہیں۔</p>\n<p>فون یا ٹیبلٹ پر ٹیپ کر کے بدلنا وہی کام کرتا ہے۔ منتخب کرنے کے لیے تصویر ٹیپ کریں، پھر اس سیل کو ٹیپ کریں جس میں آپ اسے منتقل کرنا چاہتے ہیں، اور دو تصویریں بدل جاتی ہیں۔ چھوٹی اسکرین پر ٹچ گھسیٹنا غیر قابل اعتماد ہے، اس لیے ٹیپ طریقہ موبائل کے لیے قابل اعتماد ہے۔</p>\n<p>ترتیب اہم ہے کیونکہ آنکھ کولاج کو ترتیب سے پڑھتی ہے۔ اوپر بائیں سیل پہلے دیکھا جاتا ہے، 3 بہ 3 گرڈ میں مرکز سیل آنکھ کھینچتا ہے، اور نیچے دائیں سیل آخر میں دیکھا جاتا ہے۔ مضبوط ترین تصویر کو اپنے چنے ہوئے لے آؤٹ کے سب سے نمایاں سیل میں رکھیں۔</p>\n<h2 id=\"adjusting-splits\">تقسیم ایڈجسٹ کرنا</h2>\n<p>تقسیم سیل کے درمیان تقسیم کرنے والی لکیریں ہیں، اور انہیں ایڈجسٹ کیا جا سکتا ہے۔ تقسیم لکیر گھسیٹیں تاکہ ایک سیل بڑا اور اس کا پڑوسی چھوٹا ہو جائے، جس سے نمایاں تصویر باقی سے زیادہ جگہ لیتی ہے۔ لے آؤٹ گرڈ رہتا ہے، مگر تناسب بدلتے ہیں۔</p>\n<p>نمایاں تصویر تقسیم ایڈجسٹ کرنے کی وجہ ہے۔ اہم موضوع کا ہیرو شاٹ بڑے سیل کا مستحق ہے، جبکہ معاون تصویریں چھوٹی ہو سکتی ہیں۔ بڑھے ہوئے مرکز سیل والا 3 بہ 3 گرڈ برابر کے سیٹ کی بجائے نمائش کے طور پر پڑھتا ہے۔</p>\n<p>اگر تقسیم غیر برابر ہو جائیں اور آپ دوبارہ شروع کرنا چاہیں تو انہیں یکساں گرڈ پر واپس لائیں۔ ٹول تقسیم کو برابر سیل پر ری سیٹ کرتا ہے، تاکہ آپ کولاج نئے سرے سے بنائے بغیر مختلف ترتیب آزما سکیں۔</p>\n<h2 id=\"gaps-and-rounded-corners\">خالی جگہیں اور گول کونے</h2>\n<p>خالی جگہ سیل کے درمیان جگہ ہے، اور یہ کولاج کا احساس طے کرتی ہے۔ صفر خالی جگہ بغیر سرحد والا ہموار کولاج بناتی ہے، جہاں تصویریں چھوتی ہیں اور ایک مسلسل تصویر بناتی ہیں۔ نظر آنے والی خالی جگہ تصویروں کو الگ فریموں میں تقسیم کرتی ہے، جو اسکریپ بک یا گیلری شکل کو سوٹ کرتی ہے۔</p>\n<p>سیل فاصلہ اور کونے کا رداس آزاد کنٹرول ہیں، اس لیے آپ مربع کونوں کے ساتھ چوڑی خالی جگہ، یا گول کونوں کے ساتھ تنگ خالی جگہ طے کر سکتے ہیں۔ جوڑ طے کرتا ہے کہ کولاج جدید، کلاسک یا کھیل کود والا لگے۔</p>\n<p>گول کونے کولاج کو نرم کرتے ہیں اور سوشل پوسٹ اور ایپ طرز گرافکس کو سوٹ کرتے ہیں۔ مربع کونے رسمی لگتے ہیں اور پرنٹ اور مصنوعات لسٹنگ کو سوٹ کرتے ہیں۔ چھوٹا رداس محفوظ پہلے سے طے شدہ ہے، جبکہ بڑا رداس ہر سیل کو گول ٹائل میں بدل دیتا ہے۔</p>\n<h2 id=\"image-fit-cover-vs-contain\">تصویر فٹ: Cover بمقابلہ Contain</h2>\n<p>Image Fit طے کرتا ہے کہ جب تصویر اپنے سیل شکل سے میل نہ کھائے تو کیا ہوتا ہے۔ Cover سیل کو کراپ کر کے مکمل بھر دیتا ہے، اس لیے کوئی خالی جگہ نہیں ہوتی مگر کنارے کٹ سکتے ہیں۔ یہ پہلے سے طے شدہ ہے، کیونکہ بھرا سیل تیار لگتا ہے۔</p>\n<p>Contain پوری تصویر کو کراپ کیے بغیر سیل کے اندر فٹ کرتا ہے، اس لیے کچھ بھی ضائع نہیں ہوتا مگر تصویر کے گرد خالی جگہ دکھائی دیتی ہے۔ یہ ان تصویروں کو سوٹ کرتا ہے جہاں ہر تفصیل اہم ہے، جیسے دستاویز یا کناروں پر متن والی مصنوعات تصویر۔</p>\n<p>جب Cover کوئی اہم چیز کراپ کرے تو Contain پر جائیں۔ تصویر کے کنارے پر چہرہ، مصنوعات لیبل، یا متن کی لکیر Cover سے کٹ سکتی ہے، اور Contain اسے سرحد کی قیمت پر بچاتا ہے۔ جب سرحد کراپ سے بدتر لگے تو Cover پر واپس جائیں۔</p>\n<h2 id=\"background-colors\">پس منظر رنگ</h2>\n<p>پس منظر رنگ تصویروں کے پیچھے کینوس بھرتا ہے اور خالی جگہوں سے دکھائی دیتا ہے۔ ٹول فوری پری سیٹ رنگ دیتا ہے، اس لیے آپ رنگ پکر کھولے بغیر صاف سفید، نرم غیر جانبدار، یا برانڈ رنگ چن سکتے ہیں۔</p>\n<p>سفید پہلے سے طے شدہ اور محفوظ ترین انتخاب ہے۔ یہ کولاج کو صاف رکھتا ہے، کسی بھی فیڈ یا صفحے سے میل کھاتا ہے، اور تصویروں کو تصویر میں واحد رنگ بناتا ہے۔ سفید پس منظر کبھی تصویروں سے نہیں لڑتا۔</p>\n<p>برانڈ رنگ کولاج کو ڈیزائن شدہ گرافک میں بدل دیتا ہے۔ خالی جگہوں میں رنگ کولاج کو مہم سے جوڑتا ہے، اور ایک ہی رنگ میں کولاج کا سیٹ پہچانا جانے والا سلسلہ بناتا ہے۔ اسے اس وقت استعمال کریں جب کولاج مجموعہ جتنا ہی اشتہار ہو۔</p>\n<h2 id=\"canvas-sizes-and-ratios\">کینوس سائز اور تناسب</h2>\n<p>کینوس سائز اور تناسب کولاج کی حتمی شکل طے کرتے ہیں۔ ٹول فوری کینوس ابعاد اور پری سیٹ تناسب دیتا ہے، اس لیے آپ پکسل حساب کیے بغیر فیڈ کے لیے مربع، کہانی کے لیے پورٹریٹ، یا بینر کے لیے چوڑی تصویر بنا سکتے ہیں۔</p>\n<p>مربع سب سے ورسٹائل شکل ہے۔ یہ فیڈ، لسٹنگ اور تھمب نیل میں کام کرتا ہے، اور ہر جگہ متوقع طور پر کراپ ہوتا ہے۔ 2 بہ 2 یا 3 بہ 3 گرڈ والا مربع کولاج محفوظ پہلے سے طے شدہ ہے جب آپ کو یقین نہ ہو کہ تصویر کہاں استعمال ہو گی۔</p>\n<p>پورٹریٹ تناسب کہانیوں اور فون وال پیپر کو سوٹ کرتے ہیں، جہاں تصویر لمبی دیکھی جاتی ہے۔ پورٹریٹ کینوس پر عمودی پٹی کہانی کی طرح پڑھتی ہے، اوپر سے نیچے، جو ترتیب میں دن یا قدم بہ قدم عمل کو سوٹ کرتی ہے۔</p>\n<h2 id=\"feature-photos\">نمایاں تصویریں</h2>\n<p>نمایاں تصویر ایک تصویر ہے جو باقی سے بڑی بنائی جاتی ہے، اور یہ کولاج کو مرکز دینے کا آسان ترین طریقہ ہے۔ آنکھ پہلے بڑی تصویر پر پڑتی ہے، پھر چھوٹی تصویروں کو دیکھتی ہے، جو کولاج کو چپٹے گرڈ کی بجائے درجہ بندی دیتی ہے۔</p>\n<p>مضبوط ترین تصویر کو نمایاں بنائیں۔ سفر کا ہیرو شاٹ، بہترین مصنوعات زاویہ، یا اہم پورٹریٹ بڑے سیل کا مستحق ہے۔ بڑی کی گئی کمزور تصویر صرف اس کی خامیوں پر توجہ کھینچتی ہے، اس لیے نمایاں کو موضوع کے ساتھ ساتھ معیار کے حساب سے بھی چنیں۔</p>\n<p>نمایاں سیل بڑا کرنے کے لیے تقسیم ایڈجسٹ کریں، یا وہ لے آؤٹ چنیں جو پہلے سے ایک سیل کو پسند کرتا ہے۔ ایک بڑھے ہوئے سیل والا 2 بہ 2 گرڈ نمائش کے طور پر پڑھتا ہے، جبکہ بڑھے ہوئے مرکز والا 3 بہ 3 گرڈ مرکز والی گیلری کے طور پر پڑھتا ہے۔</p>\n<h2 id=\"export-jpg-vs-png\">برآمد JPG بمقابلہ PNG</h2>\n<p>ٹول تیار کولاج کو JPG یا PNG کے طور پر برآمد کرتا ہے۔ JPG تصویروں اور کسی بھی کولاج کو سوٹ کرتا ہے جہاں چھوٹی فائل اہم ہو، جیسے سوشل پوسٹ یا ویب سائٹ تصویر۔ یہ اچھی طرح کمپریس ہوتا ہے اور تیزی سے لوڈ ہوتا ہے۔</p>\n<p>PNG تیز متن، چپٹے رنگ، یا شفافیت والے کولاج کو سوٹ کرتا ہے جو بچنی چاہیے۔ PNG فائل بڑی ہے، مگر یہ ہر کنارہ صاف رکھتا ہے اور شفاف جگہیں بالکل محفوظ رکھتا ہے۔ گرافکس بھاری کولاج کے لیے PNG اور تصویر بھاری کولاج کے لیے JPG چنیں۔</p>\n<p>برآمد ریزولوشن 4000 پکسل تک جاتی ہے، جو پرنٹ کے لیے کافی بڑی ہے۔ 4000 پکسل پر برآمد شدہ کولاج بڑے سائز پر صاف پرنٹ ہوتا ہے، جبکہ چھوٹی برآمد نرم پرنٹ ہوتی ہے۔ برآمد سائز منزل کے لیے چنیں: سوشل پوسٹ کو کم چاہیے، پرنٹ کو زیادہ چاہیے۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی بہت زیادہ تصویریں ہیں۔ نو مصروف تصویروں والا 3 بہ 3 گرڈ پڑھنا مشکل ہے، کیونکہ کوئی بھی تصویر کافی جگہ نہیں پاتی۔ کم، مضبوط تصویریں سفر کی ہر چیز سے بھرے گرڈ سے بہتر کولاج بناتی ہیں۔</p>\n<p>دوسری غلطی فٹ کو نظرانداز کرنا ہے۔ Cover کے تحت منظر سیل میں پورٹریٹ تصویر اپنا اوپر اور نیچے کھو دیتی ہے، جو چہرہ یا موضوع کاٹ سکتی ہے۔ تصویریں رکھنے کے بعد ہر سیل جانچیں، اور جہاں کراپ نقصان دے، فٹ بدلیں۔</p>\n<p>تیسری غلطی خالی جگہ رنگ ہے جو تصویروں سے لڑتا ہے۔ دھیمی تصویروں کے درمیان روشن خالی جگہ رنگ آنکھ کو تصویروں کی بجائے خالی جگہوں کی طرف کھینچتا ہے، اور گہرا خالی جگہ رنگ کولاج کو بھاری بنا سکتا ہے۔ سفید یا نرم غیر جانبدار محفوظ خالی جگہ رنگ ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: کولاج چیک لسٹ</h2>\n<p>ملتی جلتی روشنی والی چار سے نو مضبوط تصویریں چنیں، انہیں اپ لوڈ کریں، اور لے آؤٹ کو گرڈ خود بخود چننے دیں۔ تصویریں گھسیٹ کر یا ٹیپ کر کے بدل کر ترتیب دیں، نمایاں تصویر بڑی کریں، اور خالی جگہیں اور کونے طے کریں۔</p>\n<p>منزل کے لیے کینوس تناسب چنیں، تصویروں کے لیے JPG اور گرافکس کے لیے PNG چنیں، اور پرنٹ کے لیے 4000 پکسل تک برآمد کریں۔ ڈاؤن لوڈ سے پہلے ہر سیل کو خراب کراپ کے لیے جانچیں۔</p>\n<p>قدم بہ قدم بنانے کے لیے <a href=\"/ur/blog/photo-collage-kaise-banayein/\">How to Make a Photo Collage</a> پڑھیں، اور لے آؤٹ خیالات کے لیے <a href=\"/ur/blog/collage-layouts-grids-mood-boards/\">Collage Layouts: Grids, Mood Boards and Stories</a> دیکھیں۔ اپنا کولاج <a href=\"/ur/tasveer-collage-maker/\">تصویر کولاج میکر</a> سے بنائیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کولاج اور گرڈ تقسیم میں کیا فرق ہے؟","answer":"گرڈ تقسیم ایک تصویر کو ٹائل میں تقسیم کرتی ہے جو ایک ساتھ رکھنے پر اصل دوبارہ بناتے ہیں۔ کولاج کئی مختلف تصویروں کو ایک تصویر میں جوڑتا ہے۔ تقسیم ایک تصویر کو الگ کاٹتی ہے؛ کولاج کئی تصویروں کو ایک ساتھ لاتا ہے۔"},{"question":"ایک کولاج میں کتنی تصویریں ڈال سکتا ہوں؟","answer":"گرڈ 2 بہ 2 لے آؤٹ میں چار تصویریں یا 3 بہ 3 لے آؤٹ میں نو رکھتے ہیں، اور پٹیاں ایک قطار یا کالم میں کئی زیادہ رکھ سکتی ہیں۔ چار سے نو تصویریں عملی حد ہے؛ اس سے زیادہ ہر تصویر کو لطف اٹھانے کے لیے بہت چھوٹا بناتا ہے۔"},{"question":"کیا ایک کولاج میں پورٹریٹ اور منظر تصویریں ملا سکتا ہوں؟","answer":"جی ہاں۔ Image Fit ترتیب مرکب سنبھالتی ہے: Cover ہر سیل کو کراپ کر کے بھرتا ہے، جبکہ Contain پوری تصویر سرحد کے ساتھ دکھاتا ہے۔ تصویریں رکھنے کے بعد ہر سیل جانچیں، کیونکہ ایک رخ کو سوٹ کرنے والا فٹ دوسرے کو سوٹ نہ کرے۔"},{"question":"کولاج کے لیے کون سا برآمد سائز چنوں؟","answer":"سائز کو منزل سے ملائیں۔ سوشل پوسٹ کو صرف معتدل سائز چاہیے، جبکہ پرنٹ کو سب سے بڑی برآمد چاہیے، 4000 پکسل تک۔ سب سے بڑے سائز پر برآمد کریں جس کی آپ کو ضرورت ہو سکتی ہے، کیونکہ آپ بعد میں ہمیشہ سائز کم کر سکتے ہیں مگر پکسل واپس نہیں لا سکتے۔"},{"question":"کیا کولاج پرنٹ کے لیے کام کرتے ہیں؟","answer":"جی ہاں، جب تک آپ اعلیٰ ریزولوشن پر برآمد کریں۔ 4000 پکسل تک برآمد شدہ کولاج بڑے سائز پر صاف پرنٹ ہوتا ہے۔ تیز ترین پرنٹ کے لیے PNG کے طور پر برآمد کریں، یا تصویری پرنٹ کے لیے اعلیٰ کوالٹی JPG کے طور پر۔"},{"question":"کیا برآمد کے بعد کولاج ترمیم کر سکتا ہوں؟","answer":"آسانی سے نہیں، کیونکہ برآمد ایک چپٹی تصویر ہے۔ کام کرتے ہوئے کولاج کو ٹول میں کھلا رکھیں، یا ماخذ تصویریں محفوظ کریں تاکہ آپ اسے دوبارہ بنا سکیں۔ اصل سے دوبارہ بنانا برآمد شدہ فائل ترمیم کرنے سے تیز اور صاف ہے۔"}];
